/**
 * Lists a built chunk by source module: the generated bytes each source file contributes, from the chunk's source map
 * (build with `vite build --sourcemap`). For finding what a site's entry script carries.
 *
 * Usage: `node scripts/chunk-modules.ts <chunk.js.map> [rows]`
 *
 * @module @delorun/site-design/scripts/chunk-modules
 */
import { readFileSync } from 'node:fs'

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** Decodes one segment's base64 VLQ values. */
function vlq(segment: string): number[] {
  const out: number[] = []
  let shift = 0
  let value = 0
  for (const char of segment) {
    const digit = B64.indexOf(char)
    value += (digit & 31) << shift
    if (digit & 32) shift += 5
    else {
      out.push(value & 1 ? -(value >> 1) : value >> 1)
      value = 0
      shift = 0
    }
  }
  return out
}

const [file, rows = '40'] = process.argv.slice(2)
if (file === undefined) throw new Error('usage: chunk-modules.ts <chunk.js.map> [rows]')
const map = JSON.parse(readFileSync(file, 'utf8')) as { sources: string[]; mappings: string }
const bytes = new Map<string, number>()
let source = 0
for (const line of map.mappings.split(';')) {
  let column = 0
  let previous: { source: number; column: number } | undefined
  for (const text of line.split(',')) {
    if (text === '') continue
    const [dc = 0, ds, , ] = vlq(text)
    const next = column + dc
    if (previous !== undefined) bytes.set(map.sources[previous.source] ?? '?', (bytes.get(map.sources[previous.source] ?? '?') ?? 0) + (next - previous.column))
    column = next
    if (ds !== undefined) { source += ds; previous = { source, column } } else previous = undefined
  }
}
const total = [...bytes.values()].reduce((sum, each) => sum + each, 0)
console.log(`total attributed: ${String(total)} bytes in ${String(bytes.size)} modules`)
for (const [name, size] of [...bytes].sort((a, b) => b[1] - a[1]).slice(0, Number(rows))) console.log(`${String(size).padStart(8)}  ${name.replace(/^(\.\.\/)+/, '')}`)
